#include <bits/stdc++.h>
using namespace std;
using cd = complex<double>;

// FFT 变换，自底向上实现
void fft(vector<cd>& a, bool inv){
    int n = a.size(), j = 0;
    // 位反转置换
    for(int i = 1; i < n; ++i){
        int bit = n >> 1;
        for(; j & bit; bit >>= 1) j ^= bit;
        j |= bit;
        if(i < j) swap(a[i], a[j]);
    }
    const double PI = acos(-1);
    // 迭代合并
    for(int len = 2; len <= n; len <<= 1){
        double ang = 2 * PI / len * (inv ? -1 : 1);
        cd wlen(cos(ang), sin(ang));
        for(int i = 0; i < n; i += len){
            cd w(1);
            for(int j = 0; j < len/2; ++j){
                cd u = a[i+j];
                cd v = a[i+j+len/2] * w;
                a[i+j] = u + v;
                a[i+j+len/2] = u - v;
                w *= wlen;
            }
        }
    }
    if(inv){
        // 逆变换需除以 n
        for(cd& x : a) x /= n;
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    vector<int> qs(T);
    int mx = 0;
    for(int i = 0; i < T; ++i){
        cin >> qs[i];
        mx = max(mx, qs[i]);
    }

    // 标记好数
    vector<char> good(mx+1, 0);
    for(int i = 1; i <= mx; ++i){
        int x = i;
        bool ok = true;
        while(x){
            int d = x % 10;
            if(d == 2 || d == 4){
                ok = false;
                break;
            }
            x /= 10;
        }
        good[i] = ok;
    }

    // 计算 FFT 所需的长度
    int lim = 1;
    while(lim < 3*mx + 1) lim <<= 1;

    vector<cd> A(lim), B(lim);
    // A[i]=1 表示 f[i]=1，B[2*i]=1 表示 f[i]=1
    for(int i = 0; i <= mx; ++i){
        if(good[i]){
            A[i] = 1;
            B[2*i] = 1;
        }
    }

    // FFT 变换
    fft(A, false);
    fft(B, false);

    vector<long long> E1(mx+1), E2(mx+1);
    // 计算 E1 = A*A*A
    {
        vector<cd> F = A;
        for(int i = 0; i < lim; ++i) F[i] *= F[i] * A[i];
        fft(F, true);
        for(int i = 0; i <= mx; ++i)
            E1[i] = llround(F[i].real());
    }
    // 计算 E2 = A*B
    {
        vector<cd> F = A;
        for(int i = 0; i < lim; ++i) F[i] *= B[i];
        fft(F, true);
        for(int i = 0; i <= mx; ++i)
            E2[i] = llround(F[i].real());
    }

    // 计算最终答案并输出
    for(int n : qs){
        long long e3 = (n % 3 == 0 && good[n/3]) ? 1 : 0;
        long long tot = E1[n] - 3*E2[n] + 2*e3;
        cout << (tot / 6) << "\n";
    }
    return 0;
}
